import axios from 'axios';

// API ve Debug ayarları
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';
const DEBUG_MODE = process.env.NODE_ENV !== 'production';

// LCM ile görsel oluşturma servisi
export const getCombinedAuraDataWithImage = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<any> => {
  console.log('\n==== FRONTEND AURA GÖRSEL SÜRECİ BAŞLADI ====');
  console.log(`[FRONTEND_LCM] getCombinedAuraDataWithImage çağrıldı: Aura tipi=${auraType}, Kullanıcı=${username}`);
  console.log(`[FRONTEND_LCM] API endpoint: ${API_BASE_URL}/aura/combined-data`);

  try {
    // URL oluştur
    const url = `${API_BASE_URL}/aura/combined-data`;

    console.log('[FRONTEND_LCM] Backend API isteği gönderiliyor...');
    console.log(`[FRONTEND_LCM] Gönderilen cevap sayısı: ${Object.keys(answers).length}`);

    // İstek gönderme zamanını kaydet
    const startTime = Date.now();

    // Backend'e istek gönder
    const response = await axios.post(url, {
      auraType,
      username,
      answers
    });

    // İşlem süresini hesapla
    const processingTime = ((Date.now() - startTime) / 1000).toFixed(2);

    // Yanıt içeriğini analiz et
    const hasStory = !!response.data?.story;
    const hasInsights = !!response.data?.strengths && !!response.data?.potential;
    const hasImagePrompt = !!response.data?.imagePrompt;
    const hasImageUrl = !!response.data?.imageUrl;

    console.log(`[FRONTEND_LCM] Backend API yanıtı alındı (${processingTime} saniye)`);
    console.log(`[FRONTEND_LCM] Yanıt içeriği: story=${hasStory}, insights=${hasInsights}, imagePrompt=${hasImagePrompt}, imageUrl=${hasImageUrl}`);

    if (hasImagePrompt) {
      console.log(`[FRONTEND_LCM] Image Prompt: "${response.data.imagePrompt}"`);
    }

    if (hasImageUrl) {
      console.log('[FRONTEND_LCM] LCM görsel URL başarıyla alındı!');
      console.log(`[FRONTEND_LCM] Görsel URL tipi: ${response.data.imageUrl.startsWith('data:') ? 'Data URI' : 'Web URL'}`);
      console.log(`[FRONTEND_LCM] Görsel URL başlangıcı: ${response.data.imageUrl.substring(0, 50)}...`);
      console.log('[FRONTEND_LCM] Görsel arayüze eklenecek ve kullanıcıya gösterilecek');
    } else {
      console.log('[FRONTEND_LCM] LCM görseli alınamadı! imageUrl yanıtta mevcut değil');
      if (hasImagePrompt) {
        console.log('[FRONTEND_LCM] Image Prompt mevcut olmasına rağmen görsel alınamadı!');
      }
    }

    console.log('==== FRONTEND AURA GÖRSEL SÜRECİ TAMAMLANDI ====\n');
    return response.data;
  } catch (error: any) {
    console.error('[FRONTEND_LCM] Hata:', error);

    // Hata detaylarını logla
    if (error.response) {
      console.error(`[FRONTEND_LCM] API yanıt durum kodu: ${error.response.status}`);
      console.error(`[FRONTEND_LCM] API yanıt verileri: ${JSON.stringify(error.response.data).substring(0, 200)}`);
    } else if (error.request) {
      console.error('[FRONTEND_LCM] API isteği yapıldı ama yanıt alınamadı');
    } else {
      console.error(`[FRONTEND_LCM] Hata mesajı: ${error.message}`);
    }

    console.log('==== FRONTEND AURA GÖRSEL SÜRECİ BAŞARISIZ OLDU ====\n');
    throw error;
  }
};
